using System.Text.Json;
using Fanasa.AccessManagement.Web.Application.Access;
using Fanasa.AccessManagement.Web.Domain.Access;
using Fanasa.AccessManagement.Web.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace Fanasa.AccessManagement.Web.Infrastructure.Access;

public sealed class SqlAccessManagement(AccessDbContext db) : IAccessManagement
{
    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);
    private static T[] FromJson<T>(string value) => JsonSerializer.Deserialize<T[]>(value, JsonOptions) ?? [];
    private static string ToJson<T>(T value) => JsonSerializer.Serialize(value, JsonOptions);
    private static Tenant ToDomain(TenantRow x) => new(x.Id, x.Key, x.DisplayName, x.IsActive, x.CreatedAt);
    private static Product ToDomain(ProductRow x) => new(x.Id, x.Key, x.DisplayName, x.Audience, x.RepositoryUrl, x.CenterSlug, JsonSerializer.Deserialize<Dictionary<string, string>>(x.AttributesJson, JsonOptions) ?? []);
    public IReadOnlyCollection<Tenant> GetTenants() => db.Tenants.AsNoTracking().OrderBy(x => x.DisplayName).Select(ToDomain).ToArray();
    public Tenant CreateTenant(string key, string displayName) { if (string.IsNullOrWhiteSpace(key) || string.IsNullOrWhiteSpace(displayName)) throw new ArgumentException("Tenant key and display name are required."); if (db.Tenants.Any(x => x.Key == key)) throw new InvalidOperationException("A tenant with this key already exists."); var x = new TenantRow { Id = Guid.NewGuid(), Key = key.Trim(), DisplayName = displayName.Trim(), IsActive = true, CreatedAt = DateTimeOffset.UtcNow }; db.Tenants.Add(x); db.SaveChanges(); return ToDomain(x); }
    public IReadOnlyCollection<Product> GetProducts(string? centerSlug = null) => db.Products.AsNoTracking().Where(x => centerSlug == null || x.CenterSlug == centerSlug).OrderBy(x => x.DisplayName).AsEnumerable().Select(ToDomain).ToArray();
    public Product RegisterProduct(RegisterProductRequest request) { if (string.IsNullOrWhiteSpace(request.Key) || string.IsNullOrWhiteSpace(request.DisplayName) || string.IsNullOrWhiteSpace(request.CenterSlug)) throw new ArgumentException("Product key, display name and center are required."); if (db.Products.Any(x => x.Key == request.Key)) throw new InvalidOperationException("A product with this key already exists."); var center = CapabilityCatalog.All.FirstOrDefault(x => x.Name == request.CenterSlug || x.Audience == request.CenterSlug) ?? throw new ArgumentException("Center must be an official Fanasa capability center."); var x = new ProductRow { Id = Guid.NewGuid(), Key = request.Key.Trim(), DisplayName = request.DisplayName.Trim(), Audience = request.Audience.Trim(), RepositoryUrl = request.RepositoryUrl, CenterSlug = center.Audience, AttributesJson = ToJson(request.Attributes ?? new Dictionary<string, string>()) }; db.Products.Add(x); db.SaveChanges(); return ToDomain(x); }
    public IReadOnlyCollection<ProductClient> GetClients(Guid productId) => db.ProductClients.AsNoTracking().Where(x => x.ProductId == productId).OrderBy(x => x.DisplayName).AsEnumerable().Select(x => new ProductClient(x.Id, x.ProductId, x.Key, x.DisplayName, x.ClientType, FromJson<string>(x.RedirectUrisJson), FromJson<string>(x.AllowedScopesJson), x.IsActive)).ToArray();
    public ProductClient RegisterClient(Guid productId, RegisterClientRequest request) { if (!db.Products.Any(x => x.Id == productId)) throw new KeyNotFoundException("Product was not found."); var x = new ProductClientRow { Id = Guid.NewGuid(), ProductId = productId, Key = request.Key.Trim(), DisplayName = request.DisplayName.Trim(), ClientType = request.ClientType, RedirectUrisJson = ToJson(request.RedirectUris ?? []), AllowedScopesJson = ToJson(request.AllowedScopes ?? []), IsActive = true }; db.ProductClients.Add(x); db.SaveChanges(); return new(x.Id, x.ProductId, x.Key, x.DisplayName, x.ClientType, request.RedirectUris ?? [], request.AllowedScopes ?? [], true); }
    public IReadOnlyCollection<ContractEntitlement> GetEntitlements(Guid tenantId) => db.ContractEntitlements.AsNoTracking().Where(x => x.TenantId == tenantId).OrderByDescending(x => x.UpdatedAt).AsEnumerable().Select(x => new ContractEntitlement(x.Id, x.TenantId, x.ExternalContractId, x.ProductKey, x.CenterSlug, x.PlanKey, x.IncludedQuantity, x.Unit, x.EffectiveFrom, x.EffectiveTo, x.Status, x.UpdatedAt)).ToArray();
    public ContractEntitlement ApplyContractEvent(ContractLifecycleEvent message) { if (!db.Tenants.Any(x => x.Id == message.TenantId)) throw new KeyNotFoundException("Tenant was not found."); var x = db.ContractEntitlements.FirstOrDefault(y => y.TenantId == message.TenantId && y.ExternalContractId == message.ContractId && y.ProductKey == message.ProductKey && y.CenterSlug == message.CenterSlug) ?? new ContractEntitlementRow { Id = Guid.NewGuid(), TenantId = message.TenantId, ExternalContractId = message.ContractId, ProductKey = message.ProductKey, CenterSlug = message.CenterSlug }; x.PlanKey = message.PlanKey; x.IncludedQuantity = message.IncludedQuantity; x.Unit = message.Unit; x.EffectiveFrom = message.EffectiveAt; x.UpdatedAt = DateTimeOffset.UtcNow; x.Status = message.EventType switch { "ContractActivated" or "ContractRenewed" => "active", "ContractSuspended" => "suspended", "ContractExpired" => "expired", _ => throw new ArgumentException("Unsupported contract event.") }; if (x.Id == Guid.Empty) db.ContractEntitlements.Add(x); db.SaveChanges(); return new(x.Id, x.TenantId, x.ExternalContractId, x.ProductKey, x.CenterSlug, x.PlanKey, x.IncludedQuantity, x.Unit, x.EffectiveFrom, x.EffectiveTo, x.Status, x.UpdatedAt); }
    public UsageEvent RecordUsage(RecordUsageCommand command) { if (!db.Tenants.Any(x => x.Id == command.TenantId)) throw new KeyNotFoundException("Tenant was not found."); if (command.Quantity < 0 || string.IsNullOrWhiteSpace(command.IdempotencyKey)) throw new ArgumentException("Quantity must be non-negative and idempotency key is required."); var old = db.UsageEvents.FirstOrDefault(x => x.IdempotencyKey == command.IdempotencyKey); if (old is not null) return new(old.Id, old.TenantId, old.ProductKey, old.CenterSlug, old.Metric, old.Quantity, old.Unit, old.OccurredAt, old.Source, old.IdempotencyKey, old.CorrelationId, old.RecordedAt); var x = new UsageEventRow { Id = Guid.NewGuid(), TenantId = command.TenantId, ProductKey = command.ProductKey, CenterSlug = command.CenterSlug, Metric = command.Metric, Quantity = command.Quantity, Unit = command.Unit, OccurredAt = command.OccurredAt, Source = command.Source, IdempotencyKey = command.IdempotencyKey, CorrelationId = command.CorrelationId, RecordedAt = DateTimeOffset.UtcNow }; db.UsageEvents.Add(x); db.SaveChanges(); return new(x.Id, x.TenantId, x.ProductKey, x.CenterSlug, x.Metric, x.Quantity, x.Unit, x.OccurredAt, x.Source, x.IdempotencyKey, x.CorrelationId, x.RecordedAt); }
    public IReadOnlyCollection<UsageSummary> GetUsage(Guid tenantId, DateTimeOffset from, DateTimeOffset to) => db.UsageEvents.AsNoTracking().Where(x => x.TenantId == tenantId && x.OccurredAt >= from && x.OccurredAt <= to).AsEnumerable().GroupBy(x => new { x.TenantId, x.ProductKey, x.CenterSlug, x.Metric, x.Unit }).Select(g => new UsageSummary(g.Key.TenantId, g.Key.ProductKey, g.Key.CenterSlug, g.Key.Metric, g.Sum(x => x.Quantity), g.Key.Unit, g.Count(), from, to)).ToArray();
    public PricingPlan RegisterPlan(RegisterPlanRequest request) { if (!db.Products.Any(x => x.Key == request.ProductKey)) throw new KeyNotFoundException("Product was not found."); var x = new PricingPlanRow { Id = Guid.NewGuid(), ProductKey = request.ProductKey, Key = request.Key, DisplayName = request.DisplayName, BillingMode = request.BillingMode, Currency = request.Currency, FixedMonthlyAmount = request.FixedMonthlyAmount, IncludedCredit = request.IncludedCredit, IsActive = true }; db.PricingPlans.Add(x); db.SaveChanges(); return new(x.Id, x.ProductKey, x.Key, x.DisplayName, x.BillingMode, x.Currency, x.FixedMonthlyAmount, x.IncludedCredit, x.IsActive); }
    public IReadOnlyCollection<PricingPlan> GetPlans(string? productKey = null) => db.PricingPlans.AsNoTracking().Where(x => productKey == null || x.ProductKey == productKey).AsEnumerable().Select(x => new PricingPlan(x.Id, x.ProductKey, x.Key, x.DisplayName, x.BillingMode, x.Currency, x.FixedMonthlyAmount, x.IncludedCredit, x.IsActive)).ToArray();
    public PricingRule AddPricingRule(Guid planId, AddPricingRuleRequest request) { if (!db.PricingPlans.Any(x => x.Id == planId)) throw new KeyNotFoundException("Pricing plan was not found."); var x = new PricingRuleRow { Id = Guid.NewGuid(), PlanId = planId, Metric = request.Metric, Unit = request.Unit, UnitPrice = request.UnitPrice, IncludedQuantity = request.IncludedQuantity, MaximumQuantity = request.MaximumQuantity }; db.PricingRules.Add(x); db.SaveChanges(); return new(x.Id, x.PlanId, x.Metric, x.Unit, x.UnitPrice, x.IncludedQuantity, x.MaximumQuantity); }
    public AccountBalance GetBalance(Guid tenantId, string accountType = "consumer") { var x = db.AccountBalances.Find(tenantId, accountType); if (x is null) { x = new AccountBalanceRow { TenantId = tenantId, AccountType = accountType, Currency = "IRR", UpdatedAt = DateTimeOffset.UtcNow }; db.AccountBalances.Add(x); db.SaveChanges(); } return new(x.TenantId, x.AccountType, x.Available, x.Reserved, x.Currency, x.UpdatedAt); }
    public UsageCharge CalculateCharge(Guid tenantId, string productKey, string metric, decimal quantity, string idempotencyKey) { var old = db.UsageCharges.FirstOrDefault(x => x.IdempotencyKey == idempotencyKey); if (old is not null) return new(old.Id, old.TenantId, old.ProductKey, old.Metric, old.Quantity, old.Amount, old.Currency, old.IdempotencyKey, old.CalculatedAt); var plan = db.PricingPlans.FirstOrDefault(x => x.ProductKey == productKey && x.IsActive) ?? throw new InvalidOperationException("No active pricing plan exists for this product."); var rule = db.PricingRules.FirstOrDefault(x => x.PlanId == plan.Id && x.Metric == metric) ?? throw new InvalidOperationException("No pricing rule exists for this metric."); var x = new UsageChargeRow { Id = Guid.NewGuid(), TenantId = tenantId, ProductKey = productKey, Metric = metric, Quantity = quantity, Amount = Math.Max(0, quantity - rule.IncludedQuantity) * rule.UnitPrice, Currency = plan.Currency, IdempotencyKey = idempotencyKey, CalculatedAt = DateTimeOffset.UtcNow }; db.UsageCharges.Add(x); db.SaveChanges(); return new(x.Id, x.TenantId, x.ProductKey, x.Metric, x.Quantity, x.Amount, x.Currency, x.IdempotencyKey, x.CalculatedAt); }
    public RevenueSnapshot GetRevenue(string productKey, DateTimeOffset from, DateTimeOffset to) { var x = db.UsageCharges.AsNoTracking().Where(y => y.ProductKey == productKey && y.CalculatedAt >= from && y.CalculatedAt <= to).ToArray(); var gross = x.Sum(y => y.Amount); return new(productKey, x.FirstOrDefault()?.Currency ?? "IRR", gross, gross * .7m, gross * .3m, x.Select(y => y.TenantId).Distinct().Count(), from, to); }
    public TenantSubscription Subscribe(CreateSubscriptionRequest request) { if (!db.Tenants.Any(x => x.Id == request.TenantId)) throw new KeyNotFoundException("Tenant was not found."); if (!db.PricingPlans.Any(x => x.Id == request.PricingPlanId && x.ProductKey == request.ProductKey)) throw new KeyNotFoundException("Pricing plan was not found for this product."); var x = new TenantSubscriptionRow { Id = Guid.NewGuid(), TenantId = request.TenantId, ProductKey = request.ProductKey, PricingPlanId = request.PricingPlanId, Status = "active", StartedAt = DateTimeOffset.UtcNow, RenewsAt = DateTimeOffset.UtcNow.AddMonths(1), SeatLimit = request.SeatLimit }; db.TenantSubscriptions.Add(x); db.SaveChanges(); return new(x.Id, x.TenantId, x.ProductKey, x.PricingPlanId, x.Status, x.StartedAt, x.RenewsAt, x.SeatLimit, x.ActiveSeats); }
    public IReadOnlyCollection<TenantSubscription> GetSubscriptions(Guid tenantId) => db.TenantSubscriptions.AsNoTracking().Where(x => x.TenantId == tenantId).AsEnumerable().Select(x => new TenantSubscription(x.Id, x.TenantId, x.ProductKey, x.PricingPlanId, x.Status, x.StartedAt, x.RenewsAt, x.SeatLimit, x.ActiveSeats)).ToArray();
    public TenantUser AddUser(AddTenantUserRequest request) { if (!db.Tenants.Any(x => x.Id == request.TenantId)) throw new KeyNotFoundException("Tenant was not found."); if (db.TenantUsers.Any(x => x.TenantId == request.TenantId && x.KeycloakSubject == request.KeycloakSubject)) throw new InvalidOperationException("User is already a member of this tenant."); var x = new TenantUserRow { Id = Guid.NewGuid(), TenantId = request.TenantId, KeycloakSubject = request.KeycloakSubject, DisplayName = request.DisplayName, IsActive = true, JoinedAt = DateTimeOffset.UtcNow }; db.TenantUsers.Add(x); db.SaveChanges(); return new(x.Id, x.TenantId, x.KeycloakSubject, x.DisplayName, x.IsActive, x.JoinedAt); }
    public IReadOnlyCollection<TenantUser> GetUsers(Guid tenantId) => db.TenantUsers.AsNoTracking().Where(x => x.TenantId == tenantId).OrderBy(x => x.DisplayName).AsEnumerable().Select(x => new TenantUser(x.Id, x.TenantId, x.KeycloakSubject, x.DisplayName, x.IsActive, x.JoinedAt)).ToArray();
    public AccessRole CreateRole(CreateRoleRequest request) { if (!db.Tenants.Any(x => x.Id == request.TenantId)) throw new KeyNotFoundException("Tenant was not found."); var x = new AccessRoleRow { Id = Guid.NewGuid(), TenantId = request.TenantId, ProductKey = request.ProductKey, Key = request.Key, DisplayName = request.DisplayName, PermissionsJson = ToJson(request.Permissions) }; db.AccessRoles.Add(x); db.SaveChanges(); return new(x.Id, x.TenantId, x.ProductKey, x.Key, x.DisplayName, request.Permissions); }
    public IReadOnlyCollection<AccessRole> GetRoles(Guid tenantId, string? productKey = null) => db.AccessRoles.AsNoTracking().Where(x => x.TenantId == tenantId && (productKey == null || x.ProductKey == productKey)).AsEnumerable().Select(x => new AccessRole(x.Id, x.TenantId, x.ProductKey, x.Key, x.DisplayName, FromJson<string>(x.PermissionsJson))).ToArray();
}
